// In comparison task, enhance mismatch reporting:
task check_outputs(input [31:0] expected, input [31:0] actual, input int vec_idx);
  if (expected !== actual) begin
    $error("Vector %0d MISMATCH: expected=0x%08x actual=0x%08x", vec_idx, expected, actual);
    $error("  ref_required: exp=%0d act=%0d", expected[0], actual[0]);
    $error("  ref_urgent:   exp=%0d act=%0d", expected[1], actual[1]);
  end
endtask
